import type { PointKey } from "../types";

/**
 * Textes dédiés par planète × 12 maisons, sur le même principe que
 * planet-in-sign.ts : ce que la maison prend comme couleur avec cette
 * planète, où ça coince concrètement, ce qu'il y a à apprendre, mais avec
 * une structure de phrase volontairement variée d'un texte à l'autre
 * plutôt qu'un gabarit fixe. Couverture volontairement partielle pour
 * l'instant, les combinaisons non couvertes retombent sur le gabarit
 * générique de describePlanetInHouse dans compose.ts.
 */
export const PLANET_IN_HOUSE: Partial<Record<PointKey, Record<number, string>>> = {
  sun: {
    1: "Avec le Soleil en maison I, l'identité s'affiche en pleine lumière dès le premier regard : la présence se lit dans le corps, la voix, la façon d'entrer quelque part, et on sait vite à qui l'on a affaire. Ce besoin d'être vu a un revers bien concret, la difficulté à céder la scène à quelqu'un d'autre, une confiance qui masque parfois une vraie dépendance au regard des autres pour se sentir exister. La vitalité n'a pourtant pas besoin d'un public pour être réelle.",
    2: "Le Soleil en maison II ancre l'identité dans le tangible : ce qu'on possède, ce qu'on gagne, ce qu'on construit de ses mains, avec souvent un vrai talent pour faire fructifier des ressources. Le risque est de confondre les deux plans, de faire dépendre l'estime de soi du solde du compte en banque ou de chercher sans cesse à prouver sa valeur par ce qu'on accumule ; la valeur personnelle, elle, précède ce qu'elle produit, elle ne s'y résume pas.",
    3: "Le Soleil en maison III s'exprime par la parole, la curiosité et le lien immédiat, fratrie, voisinage, échanges du quotidien : on se sent le plus soi-même en apprenant, en discutant, en reliant des idées entre elles. Cette identité si mobile s'éparpille facilement sur trop de sujets à la fois, cherchant une validation dans chaque échange plutôt que dans une pensée réellement approfondie, alors que certaines idées mériteraient d'être creusées jusqu'au bout plutôt que simplement évoquées.",
    4: "Il arrive que l'identité, avec le Soleil en maison IV, se confonde avec un rôle familial hérité : on porte l'histoire des siens au point de ne plus très bien savoir ce qui, dans cette identité, appartient vraiment en propre. Le Soleil y enracine pourtant aussi le besoin réel de sécurité affective, ce sentiment de n'être pleinement soi que dans un cadre familier avant d'oser se montrer ailleurs. Le foyer reste une base, pas la totalité de qui l'on est.",
    5: "Le Soleil en maison V s'exprime pleinement dans la créativité, le jeu, l'amour et tout ce qui donne envie d'être admiré : on se sent le plus vivant en créant, en aimant sans retenue, en étant vu et applaudi pour ce qu'on fait. Le point faible se loge dans l'admiration elle-même : sans elle, on a du mal à se sentir réel, jusqu'à dramatiser une situation qui ne l'exigeait pas simplement pour continuer à capter l'attention. Continuer à créer même sans public, pour la seule joie du geste, voilà ce qu'il reste à apprendre.",
    6: "Compétence, utilité, soin apporté au quotidien : voilà comment le Soleil en maison VI construit l'identité, avec un vrai plaisir à tenir une routine avec rigueur et à se sentir pleinement soi en étant capable. Mais cette identité si centrée sur l'utilité s'effondre facilement dès qu'on ne se sent plus indispensable, et pousse vers un perfectionnisme épuisant où toute la valeur personnelle finit suspendue au travail accompli, alors qu'elle ne se mérite pas uniquement par ce qu'on produit.",
    7: "Le Soleil en maison VII se révèle pleinement dans le miroir de l'autre, comme si l'identité avait besoin d'un vis-à-vis pour se préciser : c'est souvent dans la relation, l'engagement ou le face-à-face qu'on se sent le plus complètement soi-même. Le risque, cela dit, est de s'y dissoudre hors de la relation, de chercher chez l'autre ce qui devrait se construire en soi, ou de définir sa valeur uniquement par le regard d'un partenaire. Bâtir une identité qui tient debout seule, avant même de se refléter dans l'autre, reste le vrai terrain de travail.",
    8: "Crises, transformations, intimité profonde, tout ce qui touche à ce qui reste habituellement caché : c'est là que le Soleil en maison VIII sent l'identité la plus vraie. Le besoin d'intensité qui en découle a un prix, un vide ressenti dans le calme, une tendance à rechercher la crise pour se sentir vivant, une vraie difficulté à se montrer vulnérable malgré une profondeur réelle. Exister pleinement, pourtant, ne demande pas toujours une transformation ou une épreuve pour se justifier.",
    9: "Le Soleil en maison IX s'exprime à travers la quête de sens, les croyances, les études supérieures et tout horizon qui dépasse le quotidien : on se sent le plus soi-même en explorant, en enseignant, en élargissant sa vision du monde. Cette identité si attachée à sa propre vérité glisse facilement vers le dogmatisme, liant l'estime de soi à l'idée d'avoir raison plutôt qu'à une ouverture réelle. Rester soi-même n'empêche pourtant pas d'accueillir une vision différente de la sienne.",
    10: "Être vu et valorisé pour ce qu'on accomplit : voilà ce qui, avec le Soleil en maison X, fait sentir le plus soi-même, avec souvent une vraie vocation à occuper une position visible dans le rôle public, la carrière et la reconnaissance. Sans reconnaissance extérieure, le revers apparaît vite : un effondrement possible, un épuisement au nom de l'image, une tendance à négliger tout ce qui, en soi, ne se montre pas. La valeur personnelle ne dépend pourtant pas uniquement du titre qu'on porte.",
    11: "Le Soleil en maison XI s'exprime pleinement dans le collectif : groupes, amitiés, causes partagées et vision d'avenir deviennent le lieu où l'identité se sent la plus vivante, portée par un sentiment réel d'appartenance. Elle risque cependant de s'y diluer, de se fondre dans une cause ou une bande d'amis au point de perdre ce qui la rend singulière ; rester pleinement soi tout en appartenant vraiment à un collectif, c'est justement l'équilibre à trouver.",
    12: "Loin des projecteurs que d'autres placements recherchent naturellement, le Soleil en maison XII vit l'identité en retrait : elle se sent le plus vraie dans l'invisible, le spirituel, le service discret ou l'introspection. Cette faible attirance pour la visibilité rend parfois difficile de revendiquer sa place, laisse un sentiment de transparence, ou pousse au sacrifice au point de ne plus savoir ce qu'on veut vraiment pour soi-même. Revendiquer une identité ne demande pas d'être constamment vue, mais demande d'exister, au moins, pour soi.",
  },
  moon: {
    1: "Avec la Lune en maison I, les émotions affleurent directement à la surface : l'humeur se lit sur le visage ou dans l'attitude avant même qu'un mot soit prononcé, et la sensibilité colore la toute première impression. Cette transparence a un prix, une image de soi qui varie au fil de l'humeur du moment, au point que les autres croient connaître l'état intérieur avant qu'il ait été partagé. Le ressenti peut informer la présence sans la dicter entièrement, c'est là tout l'apprentissage.",
    2: "La Lune en maison II lie la sécurité émotionnelle au tangible : avoir des réserves, un cadre matériel stable, apaise profondément, au point de chercher parfois du réconfort dans la nourriture, les achats ou l'accumulation. Le revers, c'est une anxiété financière hors de proportion avec la réalité, une estime de soi qui fluctue au rythme du compte en banque. La sécurité la plus solide se construit pourtant d'abord à l'intérieur, avant de se loger dans ce qu'on possède.",
    3: "Parler apaise la Lune en maison III : les échanges avec la fratrie, le voisinage, les conversations du quotidien nourrissent directement l'équilibre émotionnel. Mais cette sensibilité si liée à la parole peut aussi basculer d'humeur au fil d'une simple conversation, cherchant dans les mots une réassurance que seul un ressenti stabilisé de l'intérieur pourrait vraiment apporter ; tout ce qui se ressent n'a pas besoin d'être dit à voix haute pour être vrai.",
    4: "La Lune est chez elle en maison IV : le besoin de racines, de foyer et de sécurité affective y est le plus fondamental, souvent porté par une mémoire sensorielle intense de l'enfance qui continue de colorer le présent. S'en détacher émotionnellement reste difficile, l'humeur entière pouvant dépendre des changements dans le cadre domestique. Construire un foyer intérieur, pas seulement un lieu, permettrait à la sécurité de ne plus dépendre uniquement des murs.",
    5: "La Lune en maison V trouve son apaisement dans la création, le jeu et l'amour vécu sans retenue, avec un besoin réel et profond d'être touché émotionnellement par ce qu'on fait ou par qui on aime. Ce besoin d'être adoré cherche parfois une validation romantique ou créative constante pour se sentir bien, jusqu'à dramatiser une relation ou un projet pour continuer à ressentir cette intensité. Apprendre à s'apaiser soi-même, sans attendre que l'admiration vienne de l'extérieur, voilà le terrain de maturation.",
    6: "Un quotidien bien réglé, un corps pris en charge, un sentiment d'être utile : voilà ce qui apaise profondément la Lune en maison VI, et à l'inverse, l'anxiété s'y loge facilement dans le corps. Le moindre grain de sable dans la routine peut alors déclencher une inquiétude disproportionnée, l'équilibre intérieur entier se retrouvant suspendu au stress professionnel. Prendre soin sans perdre son propre équilibre en chemin, c'est tout l'enjeu.",
    7: "La Lune en maison VII se régule au contact de l'autre, avec une vraie capacité à ressentir ce que le partenaire traverse, presque par fusion : l'humeur de la relation affecte alors profondément l'équilibre intérieur. Cette porosité fait parfois perdre son propre centre émotionnel dans une relation, absorbant les humeurs de l'autre comme si elles étaient les siennes. Le terrain de maturation est d'apprendre la proximité sans perdre son ancrage émotionnel propre.",
    8: "Rien n'est ressenti à moitié avec la Lune en maison VIII : l'intimité, la crise, la transformation attirent naturellement, avec une intuition souvent aiguë pour ce qui reste caché chez les autres. Ce ressenti si profond, difficile à partager, vire facilement à la méfiance, à la jalousie, à des humeurs extrêmes vécues en privé, la vulnérabilité restant rarement montrée malgré une profondeur bien réelle. La profondeur n'a pourtant pas besoin d'être dramatique pour être réelle.",
    9: "Voyager, apprendre, croire en quelque chose de plus grand que le quotidien : cela apaise véritablement la Lune en maison IX, comme un besoin réel d'horizon pour se sentir bien. Ce besoin de sens sert néanmoins parfois à fuir un ressenti trop inconfortable, à le noyer dans l'abstraction, le voyage ou la philosophie plutôt que de le traverser directement. Le sens aide à digérer une émotion, il ne remplace pas le fait de la ressentir.",
    10: "L'humeur se lit parfois jusque dans la vie professionnelle avec la Lune en maison X, portée par un besoin réel d'être reconnue et « portée » par sa réussite ou son rôle social. Le risque est alors de sacrifier le privé, de faire dépendre l'équilibre intérieur entier de l'image professionnelle, jusqu'à négliger des besoins émotionnels que personne ne voit. Les besoins affectifs méritent pourtant d'être pris en compte même loin des regards.",
    11: "Amitiés, groupes et causes partagées nourrissent profondément l'équilibre émotionnel de la Lune en maison XI, portée par un vrai besoin d'appartenance pour se sentir bien. Exprimer un désaccord réel devient alors difficile, de peur de perdre sa place dans le cercle : cette sensibilité si liée à l'appartenance préfère parfois se taire plutôt que risquer l'exclusion. Une appartenance vraiment sûre supporte pourtant le désaccord sans se briser.",
    12: "La vie émotionnelle de la Lune en maison XII reste largement invisible : une sensibilité intuitive, presque psychique, se tourne le plus souvent vers le retrait, le rêve ou le sacrifice discret plutôt que vers l'expression directe. Ce ressenti si privé se manifeste indirectement, par le corps, les rêves, l'envie de fuir, plutôt que d'être nommé clairement. Apprendre à mettre des mots sur ce qui se ressent, plutôt que de seulement le ressentir en silence, voilà le terrain de maturation.",
  },
  mercury: {
    1: "Mercure en maison I met l'esprit et la parole au premier plan de l'image donnée : la réflexion se voit, la répartie est rapide, on pense souvent à voix haute avant même d'avoir fini de formuler l'idée. Cette vivacité si frontale se lit parfois comme de la nervosité, pousse à parler avant d'avoir vraiment senti, trahit une pensée qui tourne sans jamais se poser. Toutes les pensées n'ont pourtant pas besoin d'un débouché verbal immédiat.",
    2: "Un vrai talent pour évaluer, négocier, chiffrer ce que les choses valent réellement : voilà ce que Mercure en maison II apporte à l'argent et aux ressources, pensés de façon concrète et précise. Cet esprit si tourné vers le calculable ramène facilement toute valeur à ce qui se compte, ressasse mentalement les questions d'argent, parle prix avant de ressentir ce qu'une chose représente vraiment. Une valeur n'a pourtant pas toujours besoin d'être quantifiable pour être réelle.",
    3: "Mercure est chez lui en maison III : l'esprit y trouve son terrain naturel, curieux de tout ce qui l'entoure immédiatement, fratrie, voisinage, petits trajets, apprentissages du quotidien, avec une vraie aisance à faire des liens et à échanger. Le revers, c'est une curiosité si mobile qu'elle saute d'un sujet à l'autre sans jamais s'y attarder, parle plus qu'elle n'écoute, multiplie les échanges superficiels plutôt qu'un vrai approfondissement. Certains sujets gagnent plus à être creusés qu'à être simplement traversés.",
    4: "On analyse volontiers, avec Mercure en maison IV, ce qui vient de l'enfance, du foyer, des schémas hérités, avec une vraie intelligence pour en comprendre les mécanismes. Sauf que cette analyse si présente sert parfois à intellectualiser ce qui devrait d'abord se ressentir, créant une distance mentale avec une vie familiale qu'on préfère comprendre plutôt que vivre pleinement. Certaines choses se sentent avant de s'expliquer.",
    5: "Les idées viennent facilement à Mercure en maison V, souvent portées par un vrai enthousiasme créatif, un esprit joueur et vif dans le badinage, la créativité et tout ce qui touche à la séduction. Cette vivacité intellectualise parfois l'amour ou la création plutôt que de les vivre pleinement, multipliant les idées sans jamais en finir une seule. Achever une idée compte pourtant autant que l'avoir eue.",
    6: "Un vrai talent pour organiser le quotidien, résoudre des problèmes concrets, optimiser une méthode : voilà ce que Mercure en maison VI apporte au travail et à la routine, pensés de façon analytique et efficace. À double tranchant, cette analyse si fine bascule facilement vers l'hypocondrie ou l'inquiétude excessive sur le corps, épuisant l'esprit à vouloir optimiser jusqu'au moindre détail. Tous les détails ne méritent pas d'être analysés.",
    7: "Mercure en maison VII engage l'esprit à travers le dialogue et le partenariat : penser à voix haute avec l'autre, valoriser une vraie connexion intellectuelle dans la relation, discuter comme une forme de proximité. Reste que cette tendance transforme parfois chaque désaccord en débat interminable, négociant la relation plutôt que de simplement la vivre. Une proximité n'a pas toujours besoin d'être discutée pour être réelle.",
    8: "Psychologie, recherche, sujets tabous : Mercure en maison VIII attire l'esprit vers ce qui reste habituellement caché, avec une vraie capacité d'investigation et de perspicacité. Cette perspicacité se retourne facilement en soupçon permanent sur les motivations des autres, en pensées qui tournent en boucle sur ce qu'on ne peut pas contrôler. Tous les mystères n'ont pourtant pas besoin d'être résolus à force d'y penser.",
    9: "Philosophie, cultures étrangères, enseignement, grandes idées : Mercure en maison IX pense grand, avec un esprit qui a besoin d'horizon pour se sentir stimulé. L'envers du décor, c'est un enthousiasme qui s'éparpille sur trop de visions à la fois sans jamais les ancrer, glissant vers un ton professoral qui tolère mal la contradiction. Les grandes idées gagnent en précision, pas en volume.",
    10: "Mercure en maison X met l'esprit au service de la carrière et de l'image publique : une communication stratégique, une intelligence sociale mise à profit pour la réputation professionnelle. Cette stratégie épuise parfois l'esprit à toujours calculer comment on est perçu, transformant chaque pensée en question de communication professionnelle. Toutes les pensées n'ont pas besoin d'un public professionnel.",
    11: "Mercure en maison XI s'épanouit dans l'échange collectif : idées qui circulent en groupe, stimulation intellectuelle par les amitiés et les causes partagées, une vraie aisance à penser à plusieurs. Non sans risque de dilution : cette stimulation disperse parfois la pensée sur trop de fils à la fois, rendant difficile de mener une idée personnelle à son terme au milieu du bruit du groupe. Une bonne idée a parfois besoin de solitude pour mûrir.",
    12: "Les idées viennent parfois du rêve ou de l'inconscient plutôt que de la logique directe avec Mercure en maison XII, qui pense de façon intuitive et peu verbale, avec une vraie sensibilité à ce qui ne se dit pas. Cette pensée si intérieure a du mal à se traduire en mots, tournant en boucle silencieusement plutôt que de se clarifier par l'échange. Certaines pensées ont besoin d'être mises en mots pour cesser de tourner en rond.",
  },
  venus: {
    1: "Vénus en maison I place le charme et le sens esthétique au cœur de l'image donnée : une présence naturellement agréable, un vrai souci d'harmonie dans la façon d'être perçu. Cette identité si tournée vers la grâce évite facilement les conflits nécessaires pour préserver l'harmonie apparente, faisant dépendre l'estime de soi du fait de plaire. Être aimé et être vrai ne sont pourtant pas toujours la même chose.",
    2: "Un vrai goût pour les belles choses, un sens esthétique qui s'exprime dans ce qu'on possède et ce dont on s'entoure : voilà ce que valorise Vénus en maison II, le confort, la beauté, le plaisir tangible. Le prix à payer se loge dans la compensation, une estime de soi qui dépend de ce qu'on possède ou de son apparence, une indulgence qui sert de réconfort face à un manque plus profond. Une valeur personnelle n'a pas besoin d'une preuve esthétique.",
    3: "Vénus en maison III donne un charme naturel dans l'échange : une parole diplomate, un vrai talent pour maintenir l'harmonie avec la fratrie et le voisinage, des conversations agréables et fluides. Sauf que ce goût pour l'harmonie esquive facilement un conflit pourtant nécessaire, préférant dire ce qui fait plaisir plutôt que ce qui est vrai. L'harmonie demande parfois un mot inconfortable pour rester honnête.",
    4: "Vénus en maison IV recherche un foyer beau et harmonieux : les liens familiaux se colorent d'affection et d'esthétique, avec un vrai talent pour apaiser les tensions à la maison. Ce besoin d'harmonie esquive parfois un conflit familial nécessaire pour préserver une paix de façade, idéalisant l'entente familiale plutôt que d'en affronter les failles réelles. Un vrai foyer peut pourtant accueillir le désaccord sans se briser.",
    5: "Vénus s'exprime pleinement en maison V : amour, créativité et plaisir coulent naturellement, avec un charme qui brille particulièrement dans la séduction et l'expression artistique. L'envers, c'est un amour du plaisir qui cherche l'admiration ou la validation romantique pour se sentir bien, glisse vers l'indulgence, peine avec un amour qui demande de l'effort plutôt qu'un plaisir immédiat. Un amour qui demande des efforts reste un amour véritable.",
    6: "Vénus en maison VI cherche l'harmonie jusque dans le travail et la routine : un cadre professionnel agréable, un vrai soin esthétique apporté au corps et au quotidien. Ce même besoin d'harmonie esquive un conflit de travail pourtant nécessaire, et l'indulgence fragilise une routine ou une santé qui demanderaient plus de rigueur. L'harmonie passe parfois par affronter ce qui est inconfortable.",
    7: "Vénus est chez elle en maison VII : le partenariat est profondément valorisé, avec un vrai don pour le compromis et une aisance naturelle dans la relation à deux. À ceci près que ce talent pour l'harmonie évite parfois tout conflit au prix de ses propres besoins, choisissant un partenaire pour la paix qu'il apporte plutôt que pour une vraie profondeur. Un partenariat réel survit au désaccord, il ne l'évite pas.",
    8: "Vénus en maison VIII recherche une intimité profonde : attirée par ce qui est intense ou transformateur dans l'amour, par ce qui reste habituellement caché dans les liens et les ressources partagées. Cet amour de l'intensité s'emmêle parfois avec la possessivité ou la jalousie, utilisant le charme pour garder une emprise sur l'autre plutôt que pour se rapprocher vraiment. L'intimité n'a pas besoin d'intensité pour être réelle.",
    9: "Vénus en maison IX trouve la beauté dans l'ailleurs : cultures étrangères, philosophie, voyage nourrissent un sens esthétique et romantique élargi par l'exploration. Cette attirance idéalise volontiers un amour ou une croyance parce qu'ils viennent d'ailleurs, évitant une intimité réelle et proche au profit de l'idée d'une aventure. Ce qui est beau tout près mérite la même attention que ce qui est loin.",
    10: "Vénus en maison X met le charme au service de l'image publique et de la carrière : une aisance diplomate professionnelle, un sens esthétique valorisé socialement. Le revers, c'est un besoin de plaire qui façonne les valeurs et les choix de carrière selon ce qui est bien vu plutôt que selon ce qui comble vraiment. Ce qu'on valorise en privé compte autant que ce qu'on admire en public.",
    11: "Vénus en maison XI valorise l'amitié et l'appartenance : un charme qui brille en groupe, un vrai talent diplomate au sein des causes et des collectifs partagés. Ce besoin d'harmonie esquive néanmoins un désaccord réel au sein du groupe par peur de perdre sa place, choisissant ses amis ou ses causes pour la paix plutôt que pour l'honnêteté. Une appartenance vraie peut aussi accueillir le désaccord.",
    12: "Vénus en maison XII vit l'amour et la beauté en privé : une sensibilité esthétique discrète, une vraie capacité d'amour inconditionnel ou de sacrifice silencieux pour l'autre. Cet amour si discret se donne à distance, peine à recevoir en retour, confond parfois sacrifice de soi et amour véritable. L'amour donné mérite aussi d'être reçu.",
  },
  mars: {
    1: "Mars en maison I donne une présence affirmée et directe : on agit avant de trop réfléchir, l'énergie se voit immédiatement dans le corps et l'attitude, avec une vraie impatience à passer à l'action. Cette affirmation si frontale bascule vite vers la colère, l'impulsivité, un conflit qui se lit sur le visage avant même d'être formulé en mots. Une action n'a pourtant pas besoin d'être instantanée pour être efficace.",
    2: "Mars en maison II canalise l'énergie vers l'acquisition et la construction de ressources : une vraie combativité pour gagner sa vie, un désir réel de posséder ce pour quoi on se bat. Le revers, c'est une combativité qui devient dépense impulsive ou conflit ouvert autour de l'argent, confondant valeur personnelle et capacité à obtenir. La patience rapporte souvent plus que la force en matière d'argent.",
    3: "Mars en maison III donne une parole vive et directe : la répartie est rapide, l'esprit compétitif dans l'échange, avec une vraie énergie dans les discussions avec la fratrie et le voisinage. Sauf que cette vivacité glisse facilement vers l'attaque dans la conversation, l'impatience à écouter, le désaccord transformé en dispute pour un détail. Avoir raison ne demande pas de gagner chaque échange.",
    4: "Mars en maison IV enracine l'énergie dans la défense du foyer et de la famille : une vraie combativité protectrice, parfois aussi des tensions ou des conflits directement vécus en famille. Cette énergie protectrice se déclenche parfois même quand rien ne la justifie vraiment, défendant un territoire par réflexe plutôt que par nécessité réelle. On peut défendre son foyer sans devoir constamment se battre pour lui.",
    5: "Mars en maison V poursuit l'amour et la création avec passion : une vraie audace créative, un esprit compétitif dans le jeu et la séduction, une énergie qui aime conquérir plutôt qu'attendre. À double tranchant, cette passion confond parfois désir de conquête et plaisir réel, se précipitant dans des choix romantiques ou créatifs sans les avoir vraiment sentis. Une passion n'a pas besoin de conquête pour être réelle.",
    6: "Mars en maison VI canalise une énergie combative dans le travail et la routine : une vraie productivité, un besoin réel de bouger et d'agir au quotidien, un esprit compétitif dans les tâches accomplies. Cette énergie vire facilement au surmenage, à l'irritabilité dès que la routine est perturbée, à une tension physique née de la frustration accumulée. Le repos est lui aussi productif.",
    7: "Mars en maison VII fait émerger l'affirmation de soi à travers le partenariat : une vraie énergie dans la relation, une attirance pour des partenaires dynamiques ou stimulants, un désir réel de se mesurer à l'autre. Reste que cette énergie transforme parfois la relation en lutte de pouvoir, projetant sur le partenaire une colère qui vient d'ailleurs, cherchant à gagner plutôt qu'à collaborer. Un partenariat peut accueillir l'affirmation de soi sans devenir un combat.",
    8: "Mars en maison VIII affronte la crise, la transformation et l'intimité profonde avec un vrai courage : une capacité réelle à regarder en face ce qui reste habituellement évité, une énergie puissante dans les enjeux partagés, argent, intimité, pouvoir. L'envers du décor, c'est un courage qui glisse vers des rapports de force autour de l'intimité ou des ressources, utilisant l'intensité pour garder la main, peinant à lâcher un conflit une fois engagé. Le courage n'a pas besoin de conflit pour se prouver.",
    9: "Mars en maison IX canalise l'énergie vers la conviction, la croyance et l'exploration : une vraie passion pour les idées et les grandes causes, un désir réel d'agir au nom de ce en quoi on croit. Cette conviction cherche parfois le combat idéologique plutôt que l'échange, poussant à des décisions impulsives au nom de la liberté ou d'une croyance. Une conviction n'a pas besoin de conquérir les autres visions pour rester solide.",
    10: "Mars en maison X pousse vers l'ambition et la réussite visible : une vraie combativité professionnelle, un courage réel pour viser des objectifs publics, une énergie qui n'aime pas se contenter de peu. Le hic, c'est une énergie qui crée des conflits avec l'autorité ou la concurrence, épuisant à force de courir après la reconnaissance. Une ambition tenue dans la durée porte plus loin qu'une ambition précipitée.",
    11: "Mars en maison XI canalise l'énergie dans l'action collective : une vraie combativité au service d'une cause, une énergie qui se sent stimulée par le groupe et l'objectif commun. Cette énergie crée aussi des tensions sur la direction à prendre, s'impatiente du rythme collectif, se bat pour une cause au détriment des gens qui la portent. Une cause n'est solide que grâce aux gens qui restent pour la porter.",
    12: "Mars en maison XII tourne l'énergie vers l'intérieur ou l'invisible : une force qui s'exprime discrètement ou indirectement, un courage réel dans des combats privés, démons intérieurs, travail invisible que personne ne voit. Non exprimée, cette énergie contenue ressort de façon détournée, se retourne contre soi-même en sabotage, épuise dans des combats que personne d'autre ne connaît. Certains combats ont besoin d'être mis au jour pour être vraiment gagnés.",
  },
  saturn: {
    1: "Saturne en maison I construit l'identité par la discipline et la maîtrise de soi : une présence réservée, souvent sérieuse, avec une maturité qui s'impose parfois tôt dans la vie et une vraie capacité à porter des responsabilités avant l'heure. Cette identité si construite se fige facilement en armure, redoute de montrer la moindre faille ou incompétence, se juge durement avant que personne d'autre ne le fasse. Le sérieux n'a pas besoin d'être une armure à chaque instant.",
    2: "Saturne en maison II construit une relation disciplinée et prudente à l'argent : une sécurité matérielle bâtie lentement mais durablement, un vrai sens des responsabilités financières. Cette prudence persiste pourtant même quand les ressources sont largement suffisantes, faisant dépendre la valeur personnelle de ce qu'on a gagné à la sueur de son front. Une sécurité construite patiemment n'a pas besoin d'être sans cesse remise à l'épreuve pour être fiable.",
    3: "Saturne en maison III donne un esprit structuré et sérieux : une pensée disciplinée, une vraie rigueur dans l'apprentissage et la communication, parfois plus lente mais réellement approfondie. Cette rigueur masque parfois une peur de ne pas être compris ou pris au sérieux, une relation formelle et distante avec la fratrie ou le voisinage. Comprendre n'a pas besoin d'être instantané pour être réel.",
    4: "Saturne en maison IV porte un rapport pesant ou très structuré au foyer : une vraie responsabilité envers la famille, parfois assumée tôt, des fondations bâties à force d'efforts réels plutôt qu'offertes. Ce sens du devoir reproduit parfois une distance affective transmise par la famille, fait porter le poids d'une charge familiale, rend difficile de se sentir vraiment chez soi quelque part. Un foyer construit à l'effort reste un vrai foyer.",
    5: "Saturne en maison V aborde la créativité, l'amour et le jeu avec prudence et discipline : ce qui est créé dure dans le temps, mais il faut d'abord se sentir en sécurité pour oser vraiment jouer ou aimer sans retenue. Cette prudence juge sévèrement le moindre geste créatif, laissant la peur de l'échec bloquer la spontanéité et la joie. Une création n'a pas besoin d'être parfaite pour avoir de la valeur.",
    6: "Saturne en maison VI construit une vraie maîtrise par l'effort quotidien : discipline dans le travail et la routine, exigence élevée envers soi-même, une compétence qui se bâtit avec constance plutôt qu'avec facilité. Le prix à payer, c'est un jugement sévère sur sa propre productivité, une tension physique née d'une responsabilité chroniquement portée. Le repos n'a pas besoin d'être mérité pour être légitime.",
    7: "Saturne en maison VII prend le partenariat au sérieux : un vrai engagement, un sens réel de la responsabilité envers la relation, souvent des partenaires plus mûrs ou des liens qui s'approfondissent avec le temps plutôt que dans l'urgence. Paradoxalement, cette prise au sérieux retarde parfois le pas vers la relation, installe une froideur ou une distance affective, fait choisir le devoir plutôt qu'une vraie intimité. La proximité n'a pas besoin d'être contrôlée pour rester sûre.",
    8: "Saturne en maison VIII affronte la crise, la transformation et les ressources partagées avec une discipline et un courage réels : une vraie maîtrise face à ce qui est habituellement redouté, une capacité à traverser l'épreuve avec structure plutôt qu'à la fuir. Ce courage se transforme en peur de perdre la maîtrise dans l'intimité ou la crise, en difficulté à faire confiance à d'autres avec sa vulnérabilité. La confiance n'exige pas le contrôle.",
    9: "Saturne en maison IX construit une vision du monde solide et éprouvée : une approche disciplinée de la croyance, de la philosophie et des études supérieures, une conviction qui se bâtit avec le temps plutôt que par enthousiasme passager. Cette solidité glisse parfois vers le dogmatisme, la peur d'avoir tort en public, des convictions tenues comme une protection contre l'incertitude plutôt que comme une vraie recherche. Une conviction solide peut supporter d'être questionnée.",
    10: "Saturne est chez lui en maison X : la carrière et la réputation se construisent avec une vraie maîtrise, une discipline et une ambition de long terme, souvent une réussite gagnée à force d'efforts plutôt qu'offerte. Cette identité si construite par l'accomplissement s'effondre sans reconnaissance professionnelle, se juge durement au moindre échec public. La valeur personnelle ne dépend pas uniquement du titre gagné.",
    11: "Saturne en maison XI construit des amitiés prudentes et engagées : moins nombreuses mais souvent plus durables, un vrai sens des responsabilités envers les causes et les collectifs choisis avec soin. Cette prudence crée un sentiment de solitude malgré des liens réels, une peur de ne jamais vraiment appartenir même au sein d'un cercle choisi. Appartenir vraiment ne demande pas d'être indispensable au groupe.",
    12: "Saturne en maison XII tourne la discipline vers l'intérieur : une responsabilité vécue en privé, une vraie force construite dans la solitude ou une épreuve invisible, souvent le poids de charges que personne d'autre ne voit. Cette discipline intérieure nourrit la peur d'être vraiment vu, des tendances à s'auto-punir en silence plutôt qu'à demander de l'aide. Certains fardeaux s'allègent une fois partagés.",
  },
  fortune: {
    1: "La Part de Fortune en maison I déclenche le bien-être dans la présence elle-même : être simplement soi, sans calcul ni stratégie, suffit souvent à attirer une aisance naturelle dans la façon dont on est perçu et accueilli. Cette facilité de premier abord pousse parfois à ne compter que sur le charme naturel, sans jamais aller plus loin pour concrétiser ce qu'il ouvre. Cette aisance est un point de départ à cultiver, pas une stratégie suffisante à elle seule.",
    2: "La Part de Fortune en maison II déclenche le bien-être dans un rapport naturellement fluide à l'argent et aux ressources : gagner sa vie, faire fructifier ce qu'on possède, semble couler avec moins de friction que pour d'autres. Le piège, c'est de croire que les choses « s'arrangeront toujours », sans jamais vraiment gérer activement ce qui, justement, se construit facilement. Le terrain de maturation est d'apprendre à entretenir ce que cette facilité apporte plutôt qu'à le tenir pour acquis.",
    3: "La Part de Fortune en maison III déclenche le bien-être dans l'échange quotidien : parler, apprendre, se relier à la fratrie ou au voisinage semble naturellement facile, presque sans effort conscient. Cette aisance de la parole peut suffire à elle seule sans jamais être approfondie par la pratique ou la persévérance qu'elle mériterait. Ce don naturel pour l'échange reste un avantage de départ, pas un aboutissement.",
    4: "La Part de Fortune en maison IV déclenche le bien-être dans le foyer et les racines : la sécurité affective, le sentiment d'appartenance familiale, s'installent avec une facilité que d'autres maisons n'offrent pas. Cette stabilité fait parfois oublier qu'un foyer, même naturellement accueillant, a besoin d'attention continue pour le rester. Prendre soin activement de cette base plutôt que de supposer qu'elle se maintiendra d'elle-même, voilà la leçon à emporter.",
    5: "La Part de Fortune en maison V déclenche le bien-être dans la créativité, l'amour et le plaisir : les projets créatifs, les histoires de cœur, semblent portés par une chance réelle, une facilité à être vu et apprécié. Cette aisance fait parfois croire que l'amour ou le succès créatif devraient toujours venir sans effort, avec un vrai découragement dès qu'un peu de travail s'impose. Ce don naturel mérite d'être exercé, pas seulement constaté.",
    6: "La Part de Fortune en maison VI déclenche le bien-être dans le travail quotidien, la santé et l'utilité : les routines se mettent en place avec une facilité relative, le corps semble naturellement plus équilibré. Le risque, c'est de croire qu'aucun entretien n'est nécessaire, précisément parce que cette aisance a toujours été là sans effort particulier. Le terrain de maturation est de considérer cette facilité comme une ressource à protéger par un soin régulier, pas comme une preuve qu'elle n'en a pas besoin.",
    7: "La Part de Fortune en maison VII déclenche le bien-être dans le partenariat : coopérer, s'associer, avancer à deux semble venir avec une aisance relationnelle réelle. Cette facilité peut pousser à attendre que le bon partenaire ou collaborateur se présente de lui-même, sans jamais vraiment s'investir pour le faire advenir. Cette aisance relationnelle est un cadeau à construire par une réciprocité réelle, pas seulement à espérer.",
    8: "La Part de Fortune en maison VIII fonctionne différemment des autres maisons : le bien-être ne se trouve pas dans la facilité de surface mais dans la capacité à traverser vraiment ce qui touche aux ressources partagées, à l'intimité, à la transformation. Cette recherche d'aisance peut pousser à chercher des réponses faciles à ce qui demande en réalité une vraie profondeur, en utilisant le charme pour éviter la transformation nécessaire. L'aisance ici se trouve en traversant la profondeur, pas en la contournant.",
    9: "La Part de Fortune en maison IX déclenche le bien-être dans l'exploration, l'apprentissage, les croyances et les horizons lointains : voyager, apprendre, transmettre du sens semble venir avec une facilité réelle. Cette aisance exploratoire peut servir à fuir plutôt qu'à vraiment grandir, traitant chaque nouvel horizon comme une échappatoire plutôt qu'un approfondissement. Suivre cet attrait pour le lointain jusqu'au bout, avec un engagement réel envers ce qui est appris, voilà ce qu'il y a à intégrer.",
    10: "La Part de Fortune en maison X déclenche le bien-être dans la carrière et la reconnaissance publique : la réussite professionnelle, la réputation, semblent venir avec moins de friction que pour d'autres. Cette aisance pousse parfois à attendre une reconnaissance qui arrive sans effort visible, ou à sous-estimer un vrai succès en le mettant sur le compte de la seule chance. Reconnaître pleinement la réussite que cette aisance apporte, plutôt que de la relativiser, voilà la leçon à emporter.",
    11: "La Part de Fortune en maison XI déclenche le bien-être dans les amitiés, les collectifs et les causes partagées : appartenir à un groupe, se sentir soutenu, vient avec une facilité relationnelle réelle. Cette aisance peut faire croire que le soutien collectif arrivera de lui-même, sans jamais vraiment s'investir dans les liens qui le rendent possible. Cultiver cette aisance naturelle par une présence constante, pas seulement par une disponibilité de circonstance, voilà ce qu'il y a à travailler.",
    12: "La Part de Fortune en maison XII déclenche le bien-être dans le retrait, la spiritualité, la compassion et le lâcher-prise : la solitude choisie, l'introspection, semblent apporter un apaisement réel et naturel. Ce retrait facile peut servir à fuir ce qui demanderait d'être affronté plutôt qu'à vraiment se ressourcer. Le terrain de maturation est de faire de ce retrait une restauration authentique, pas un évitement.",
  },
  jupiter: {
    1: "Jupiter en maison I déborde sur l'image donnée : la présence occupe naturellement de la place, avec une confiance et un optimisme qui se lisent souvent dans la carrure, la voix ou la façon d'entrer dans une pièce, on est vu comme quelqu'un « en plus grand » avant même d'avoir dit quoi que ce soit. Cette expansion spontanée déborde parfois en promesses trop généreuses, en confiance qui frôle l'excès, ou en une présence si large qu'elle laisse peu d'espace à ceux d'à côté. L'ampleur n'a pourtant pas besoin d'être maximale à chaque instant pour rester réelle : on peut occuper sa place sans occuper toute la pièce.",
    2: "Jupiter en maison II donne un rapport large à l'argent et à ce qui rassure matériellement : la confiance qu'il y en aura toujours assez, une générosité naturelle, souvent une vraie capacité à attirer ou faire fructifier les ressources sans s'en inquiéter constamment. Cet optimisme désaligne parfois les dépenses des moyens réels, surestime ce qu'on possède ou ce qu'un projet va rapporter, jusqu'à confondre confiance et imprudence. Un chiffre précis ne trahit pourtant pas l'abondance ressentie : la prudence budgétaire peut coexister avec la générosité plutôt que la contredire.",
    3: "Jupiter en maison III élargit tout ce qui touche à la parole et à l'entourage proche : curiosité tous azimuts, enthousiasme communicatif, une facilité à faire des liens entre des idées ou des personnes qui semblaient éloignées. Cette générosité de pensée dérape parfois en généralisations hâtives, en promesses verbales qui dépassent ce qui sera vraiment tenu, ou en une conversation si tournée vers les grandes idées qu'elle perd le détail concret. Dire moins, mais juste, porte parfois plus loin qu'un enthousiasme qui embrasse tout sans vérifier.",
    4: "Jupiter en maison IV colore le foyer et les racines d'une tonalité généreuse : une maison qui accueille largement, une famille vécue comme une ressource morale ou philosophique autant qu'affective, parfois littéralement un foyer nombreux ou en expansion. Ce besoin de voir grand dans les racines enjolive parfois une histoire familiale plus compliquée qu'elle n'y paraît, ou crée une attente irréaliste de ce qu'un foyer doit apporter. Apprendre à aimer ses racines telles qu'elles sont réellement, pas seulement dans la version agrandie qu'on préférerait raconter, voilà le terrain de maturation.",
    5: "Jupiter en maison V amplifie le plaisir, la créativité et l'amour ludique : une capacité réelle à jouer, créer et aimer sans retenue, souvent une chance perçue dans les histoires de cœur ou les projets créatifs, et un rapport généreux aux enfants quand il y en a. Cet appétit dérape parfois en excès, dépenses, promesses amoureuses, prises de risque, pris pour de la joie de vivre plutôt que pour ce qu'ils sont. Le plaisir n'a pourtant pas besoin d'être démesuré pour être pleinement ressenti.",
    6: "Jupiter en maison VI cherche du sens jusque dans le quotidien : le travail et les routines fonctionnent mieux quand ils s'inscrivent dans une perspective plus large qu'une simple tâche à accomplir, une mission, un apprentissage, une progression. Cette quête de sens rend parfois les détails répétitifs pesants, pousse à trop en promettre professionnellement ou à négliger un corps qu'on croit indestructible tant qu'on se sent porté par l'élan. La routine bien tenue est elle-même une forme de croissance, pas son contraire.",
    7: "Jupiter en maison VII fait du partenaire une figure d'ouverture : l'autre est souvent vécu comme celui ou celle qui fait grandir, élargit l'horizon, apporte une philosophie ou une culture différente, l'engagement se choisit en partie pour ce qu'il permet de devenir. Cette attente place parfois la barre trop haut, cherche un partenaire « plus grand que nature » au point de ne jamais se satisfaire de quelqu'un de réel, ou surestime la compatibilité au moment de s'engager. Faire grandir la relation elle-même plutôt que d'attendre que l'autre s'en charge seul, voilà le terrain de maturation.",
    8: "Jupiter en maison VIII aborde les crises, les ressources partagées et l'intimité profonde avec une confiance rare pour cette maison habituellement redoutée : une capacité à traverser les épreuves en y trouvant du sens, parfois une chance réelle avec l'argent des autres, héritage, association, dette bien gérée. Cet optimisme sert parfois à contourner ce qui fait vraiment mal, une positivité de façade qui empêche de vraiment traverser le deuil, la jalousie ou la peur plutôt que de les transformer. La foi en la traversée ne dispense pourtant pas de la vivre pleinement.",
    9: "Jupiter est chez lui en maison IX : philosophie, études supérieures, voyages et croyances personnelles s'articulent naturellement, avec une soif réelle de sens et d'horizon qui dépasse le quotidien, c'est souvent ici que se construit une vision du monde structurante pour toute une vie. Cette conviction glisse parfois vers le dogmatisme, l'impression de détenir une vérité plus large que celle des autres, ou une générosité d'idées qui tolère mal la contradiction. La vraie ouverture d'esprit accepte pourtant d'être questionnée, pas seulement de questionner.",
    10: "Jupiter en maison X porte la réputation et la carrière vers l'ampleur : une reconnaissance publique souvent facilitée, un charisme qui inspire confiance, une ambition qui vise large plutôt que de se contenter d'un poste modeste. Cette expansion va parfois plus vite que les fondations réelles, avec des engagements professionnels pris avant d'avoir les moyens de les tenir, ou une image publique plus grande que ce qui la soutient concrètement. Construire une réussite qui tient dans la durée, pas seulement dans l'élan du moment, voilà le terrain de maturation.",
    11: "Jupiter en maison XI élargit le réseau social et les idéaux collectifs : un cercle d'amis souvent large et varié, un vrai enthousiasme pour les causes et les projets de groupe, la conviction que l'avenir se construit collectivement. Cette générosité relationnelle reste parfois en surface, multiplie les connaissances sans vraiment approfondir les liens, ou idéalise un groupe ou une cause au point d'en ignorer les failles réelles. Choisir, parmi toutes les directions possibles, celles qui méritent un engagement réellement suivi, voilà ce qu'il y a à travailler.",
    12: "Jupiter en maison XII loge la confiance et le sens dans l'invisible : une foi intérieure, spirituelle ou intuitive, qui soutient même quand rien de concret ne la justifie, parfois une chance discrète qui agit en coulisses plutôt qu'au grand jour. Cet optimisme sert parfois à fuir ce qui est réellement caché ou douloureux, une spiritualité utilisée pour survoler plutôt que pour affronter ce que cette maison demande de regarder en face. La foi la plus solide est pourtant celle qui a traversé l'ombre, pas celle qui l'a évitée.",
  },
  uranus: {
    1: "Uranus en maison I rend l'identité imprévisible et résolument singulière : une présence qui surprend, qui refuse d'entrer dans un moule, avec souvent des changements de look ou d'attitude soudains qui déroutent l'entourage. Cette singularité si affirmée vire parfois à la provocation gratuite, change de visage juste pour se distinguer, ou empêche de se sentir stable dans sa propre peau. L'originalité n'a pourtant pas besoin d'être permanente pour rester vraie.",
    2: "Uranus en maison II donne un rapport instable et original à l'argent : les revenus peuvent varier de façon soudaine, une vraie allergie à toute dépendance financière, parfois une source de gains inattendue ou peu conventionnelle. Cette instabilité nourrit parfois une anxiété permanente sur les ressources, ou pousse à rompre un cadre stable juste pour préserver sa liberté, même quand ce cadre servait bien. La sécurité matérielle et la liberté ne sont pas nécessairement incompatibles.",
    3: "Uranus en maison III donne un esprit électrique et non conformiste : des idées qui surgissent par éclairs, un vrai talent pour voir un sujet sous un angle que personne n'avait envisagé, parfois une relation à la fratrie ou au voisinage marquée par la distance ou la rupture. Cette vivacité saute parfois d'une idée à l'autre sans jamais se poser, ou provoque pour le plaisir de bousculer plutôt que pour vraiment échanger. Une idée originale gagne à être partagée posément pour vraiment porter.",
    4: "Uranus en maison IV bouscule le rapport au foyer et aux racines : des déménagements fréquents ou soudains, une famille peu conventionnelle, parfois une rupture précoce avec le cadre familial d'origine pour affirmer sa propre voie. Ce besoin d'indépendance empêche parfois de se sentir vraiment chez soi où que ce soit, ou pousse à fuir toute racine par peur d'y être enfermé. Un foyer peut se réinventer sans devoir être totalement rejeté.",
    5: "Uranus en maison V rend la créativité et l'amour résolument hors norme : une inspiration qui frappe sans prévenir, des attirances soudaines ou électriques, un vrai besoin de liberté dans le jeu et la création. Cette électricité rend parfois difficile un engagement amoureux dans la durée, pousse à rompre dès que la relation devient trop prévisible, transforme chaque histoire en coup de foudre suivi d'une fuite. Aimer librement ne signifie pourtant pas devoir fuir dès que ça devient sérieux.",
    6: "Uranus en maison VI apporte une énergie nerveuse et innovante au travail quotidien : une vraie aptitude à réinventer une méthode, une allergie profonde à la routine figée, parfois un système nerveux sensible qui réagit vite au stress. Ce besoin de changement pousse parfois à quitter un poste dès qu'il devient trop prévisible, ou génère une tension physique liée à l'impatience chronique. Une routine peut inclure de la nouveauté sans devoir être abandonnée entièrement.",
    7: "Uranus en maison VII attire des partenariats hors norme : des partenaires souvent atypiques, indépendants ou imprévisibles, un engagement vécu différemment des attentes conventionnelles. Ce besoin de liberté provoque parfois des ruptures soudaines dès que la relation semble trop contraignante, ou attire des liens qui ne durent jamais assez pour vraiment s'approfondir. Un partenariat peut respecter la liberté de chacun sans devoir rester à distance.",
    8: "Uranus en maison VIII traverse les crises et les ressources partagées par des ruptures soudaines : des bouleversements financiers ou intimes qui arrivent sans prévenir, une vraie capacité à se réinventer complètement après un choc. Cette électricité rend parfois difficile une vulnérabilité stable dans le temps, ou pousse à fuir une intimité dès qu'elle devient trop profonde. Une transformation n'a pas besoin d'être brutale pour être réelle.",
    9: "Uranus en maison IX bouscule les croyances et la vision du monde : une pensée qui rejette les dogmes reçus, un attrait réel pour des philosophies ou des cultures radicalement différentes, parfois une conversion soudaine à une vision nouvelle. Ce besoin de rupture intellectuelle fait parfois changer de croyance aussi vite qu'on l'avait adoptée, ou rejeter une idée simplement parce qu'elle est devenue familière. Une conviction peut évoluer sans devoir être abandonnée à chaque nouvelle idée séduisante.",
    10: "Uranus en maison X marque la carrière et la réputation du sceau de l'imprévu : des changements de voie soudains, une vraie vocation à innover ou à bousculer un secteur, une réussite qui suit rarement un chemin conventionnel. Ce besoin d'indépendance provoque parfois des ruptures de carrière répétées, ou entre en conflit ouvert avec toute autorité perçue comme rigide. Une trajectoire peut rester fidèle à soi sans devoir tout renverser à chaque étape.",
    11: "Uranus est chez lui en maison XI : les amitiés, les causes collectives et la vision d'avenir s'expriment avec une aisance naturelle, souvent un vrai talent pour rassembler des gens différents autour d'une idée nouvelle. Cette aisance collective reste parfois en surface, garde une distance émotionnelle même au sein d'un groupe proche, privilégie l'idéal du groupe à la relation réelle avec chacun de ses membres. Appartenir à un collectif n'exige pourtant pas de sacrifier sa proximité avec les individus qui le composent.",
    12: "Uranus en maison XII loge le besoin de rupture dans l'invisible : des intuitions soudaines, une vie intérieure marquée par des prises de conscience brutales, parfois un sentiment de décalage profond avec le monde qui ne se dit jamais vraiment. Ce besoin de liberté intérieure coupe parfois de tout ancrage extérieur, nourrit un sentiment de ne jamais vraiment appartenir nulle part. Une part de soi peut rester libre sans devoir se couper complètement du monde partagé.",
  },
  neptune: {
    1: "Neptune en maison I rend l'image insaisissable et poreuse : une présence qui semble se fondre dans l'ambiance du moment, une sensibilité empathique qui se lit dès le premier regard, parfois une identité difficile à cerner même pour soi-même. Cette porosité efface parfois les contours de qui l'on est face aux attentes des autres, fait dépendre l'image de soi de ce que chacun projette dessus. Une identité peut rester fluide sans devoir se dissoudre complètement dans le regard d'autrui.",
    2: "Neptune en maison II brouille le rapport concret à l'argent : une intuition réelle pour ce qui a de la valeur au-delà du chiffre, parfois un flou chronique sur les questions matérielles, une générosité qui peut confiner à l'imprécision budgétaire. Cette confusion fait parfois ignorer une réalité matérielle inconfortable plutôt que de l'affronter, ou pousse à idéaliser une source de revenus qui n'existe pas vraiment. Un idéal de valeur mérite pourtant d'être vérifié par des chiffres réels, sans que cela le trahisse.",
    3: "Neptune en maison III donne une pensée intuitive et imagée : des idées qui viennent par association ou par image plutôt que par logique linéaire, une vraie sensibilité poétique dans la parole, parfois une communication avec la fratrie ou le voisinage marquée par le non-dit. Cette pensée si fluide a parfois du mal à se structurer clairement, laisse place au malentendu faute d'avoir été exprimée avec assez de netteté. Une intuition gagne en force quand elle trouve les mots pour se dire clairement.",
    4: "Neptune en maison IV enveloppe le foyer et les racines d'un flou particulier : une atmosphère familiale sensible, parfois marquée par un secret, une absence ou un non-dit qui colore durablement le sentiment de sécurité. Ce flou nourrit parfois une image enjolivée ou au contraire trouble de l'histoire familiale, difficile à démêler du ressenti réel. Un foyer intérieur solide peut pourtant se construire même sans avoir toutes les réponses sur celui d'origine.",
    5: "Neptune en maison V inspire une créativité et un amour teintés de rêve : une imagination artistique réelle, une tendance à idéaliser l'être aimé ou le projet créatif en cours, un romantisme qui cherche la fusion plus que la réalité concrète de l'autre. Cet idéal fait parfois voir chez un partenaire ou dans une création ce qui n'y est pas vraiment, jusqu'à une désillusion douloureuse quand la réalité rattrape le rêve. Aimer vraiment demande de voir l'autre tel qu'il est, pas seulement tel qu'on voudrait qu'il soit.",
    6: "Neptune en maison VI lie le quotidien à une quête de sens plus large : un vrai besoin de servir une cause qui dépasse la simple tâche à accomplir, une sensibilité corporelle qui capte facilement le stress ambiant sous forme de fatigue diffuse ou de symptômes difficiles à nommer. Ce besoin de service mène parfois à s'oublier complètement dans le travail ou le soin des autres, à ignorer des limites corporelles réelles jusqu'à l'épuisement. Prendre soin des autres suppose d'abord d'écouter ce que le corps réclame.",
    7: "Neptune en maison VII idéalise le partenariat : l'autre est souvent perçu comme une âme sœur, un partenaire choisi pour ce qu'il inspire ou incarne plutôt que pour ce qu'il est concrètement au quotidien. Cette idéalisation masque parfois des signaux réels chez un partenaire, ou installe une attente de fusion totale impossible à tenir dans la durée. Un amour réel se construit avec les failles de l'autre, pas seulement avec l'idéal qu'il inspire au départ.",
    8: "Neptune en maison VIII plonge l'intimité et les ressources partagées dans une zone trouble : une intuition puissante pour ce qui reste non-dit dans les liens profonds, parfois une confusion sur ce qui appartient vraiment à soi ou à l'autre dans une relation fusionnelle. Cette porosité rend parfois difficile de distinguer ses propres besoins de ceux du partenaire dans l'intimité ou les finances communes, jusqu'à s'y perdre complètement. Une intimité profonde peut se vivre sans dissoudre entièrement ses propres frontières.",
    9: "Neptune en maison IX élargit la quête de sens jusqu'au mysticisme : une vraie attirance pour le spirituel, les grandes croyances, une philosophie qui cherche moins à comprendre qu'à ressentir une vérité plus vaste. Cette quête sert parfois à fuir le réel plutôt qu'à l'éclairer, adopte une croyance pour échapper à une vie jugée trop ordinaire plutôt que pour vraiment y croire. Une spiritualité solide s'ancre dans le quotidien, elle ne s'y substitue pas.",
    10: "Neptune en maison X rend la carrière et la réputation publiques floues ou inspirées : une vocation souvent tournée vers l'art, le soin ou le service, parfois une image publique difficile à cerner nettement, ou une réussite qui semble se dérober juste avant d'être atteinte. Cet idéal professionnel reste parfois au stade du rêve faute de structure concrète pour le porter, ou se laisse guider par une image trop vague de ce que la réussite devrait être. Une vocation inspirée a besoin d'étapes concrètes pour ne pas rester un simple horizon.",
    11: "Neptune en maison XI porte les idéaux collectifs et les causes humanitaires : un vrai besoin d'appartenir à quelque chose qui dépasse l'intérêt individuel, une empathie réelle pour des causes larges, parfois des amitiés choisies pour ce qu'elles incarnent plutôt que pour ce qu'elles sont vraiment. Cet idéal mène parfois à idéaliser un groupe ou une cause au point d'en ignorer les failles réelles, jusqu'à une déception profonde quand la réalité du collectif rattrape le rêve porté sur lui. Une cause reste solide même vue avec ses imperfections réelles.",
    12: "Neptune est chez lui en maison XII : la vie intérieure, l'intuition et le sens du sacré y trouvent leur terrain le plus naturel, avec une porosité réelle à ce qui échappe au rationnel, rêves, art, compassion, spiritualité. Cette porosité efface parfois les limites entre soi et le monde au point de se perdre, fuit le réel par le rêve, le sommeil ou d'autres formes d'évasion plutôt que d'affronter ce qui doit l'être. Un retrait intérieur nourrit vraiment quand il reste relié, même ténuement, au monde partagé.",
  },
  pluto: {
    1: "Pluton en maison I donne une présence intense et magnétique : un regard qui semble voir au-delà des apparences, une aura de pouvoir ou de mystère qui s'impose sans effort apparent, une identité forgée par des passages transformateurs plutôt que par un développement tranquille. Cette intensité pousse parfois à vouloir tout maîtriser dans la façon dont on est perçu, ou intimide sans le vouloir des personnes qui hésitent alors à s'approcher vraiment. Une présence puissante peut pourtant aussi se rendre accessible sans rien perdre de sa profondeur.",
    2: "Pluton en maison II transforme le rapport à l'argent et aux ressources en enjeu de pouvoir : une capacité réelle à reconstruire une sécurité matérielle après une perte totale, parfois des crises financières qui obligent à tout repenser depuis zéro. Cette intensité fait parfois de l'argent un outil de pouvoir sur soi ou sur les autres, nourrit une peur profonde du manque même quand les ressources sont largement suffisantes. Une sécurité vraiment solide ne dépend pourtant pas du contrôle total de ce qu'on possède.",
    3: "Pluton en maison III donne un esprit pénétrant qui va toujours chercher sous la surface : une conversation qui évite le superficiel, un vrai talent pour percer les non-dits dans les échanges, parfois des relations avec la fratrie ou le voisinage marquées par des rapports de pouvoir ou des secrets tus. Cette perspicacité vire parfois au soupçon systématique sur les intentions des autres dans une conversation pourtant anodine. Toutes les paroles n'ont pas une intention cachée à décoder.",
    4: "Pluton en maison IV plonge le foyer et les origines dans une intensité rare : une histoire familiale souvent marquée par un secret, une crise majeure ou un pouvoir exercé de façon écrasante par une figure parentale, dont la transformation devient une tâche de toute une vie. Ce poids hérité pousse parfois à reproduire, sans le vouloir, la même dynamique de pouvoir dans son propre foyer, ou nourrit une méfiance profonde envers l'idée même de sécurité familiale. Un héritage familial lourd peut pourtant être transformé plutôt que simplement répété.",
    5: "Pluton en maison V vit la créativité et l'amour avec une intensité totale : rien n'est fait à moitié, ni une passion créative, ni un amour, avec une vraie capacité à se réinventer complètement à travers ce qu'on aime ou ce qu'on crée. Cette intensité glisse parfois vers un besoin de contrôle sur le partenaire ou l'œuvre créée, une jalousie qui naît de la peur de perdre ce qui compte le plus. Aimer intensément n'exige pourtant pas de tout maîtriser chez ce qu'on aime.",
    6: "Pluton en maison VI transforme le rapport au travail et au corps en profondeur : une capacité réelle à se réinventer professionnellement après une crise, une intuition corporelle aiguë sur ce qui doit changer avant que la santé ne l'impose de force. Cette intensité vire parfois à un perfectionnisme rigide dans le travail ou une surveillance excessive du corps, jusqu'à un épuisement né du besoin de tout maîtriser. Un vrai changement de fond n'a pourtant pas besoin d'un contrôle total pour advenir.",
    7: "Pluton en maison VII fait du partenariat un terrain de transformation profonde : des relations rarement tièdes, souvent marquées par une intensité, une fascination ou des rapports de pouvoir qui obligent à grandir. Cette intensité transforme parfois la relation en bras de fer permanent, nourrit la jalousie ou le besoin de contrôler l'autre par peur de le perdre. Un partenariat transformateur reste sain seulement s'il laisse à chacun sa propre souveraineté.",
    8: "Pluton est chez lui en maison VIII : les crises, les ressources partagées et la transformation profonde s'y expriment avec une puissance rare, une vraie capacité à traverser ce qui briserait d'autres placements et à en ressortir régénéré. Cette force se referme parfois sur elle-même, se méfie d'une vulnérabilité pourtant nécessaire pour vraiment se relier à l'autre dans l'épreuve. Une transformation partagée avec quelqu'un d'autre reste pourtant possible sans jamais perdre sa propre puissance.",
    9: "Pluton en maison IX transforme la quête de sens en obsession de vérité : une conviction qui ne se contente jamais des réponses de surface, une vraie capacité à remettre en question radicalement une croyance héritée pour en reconstruire une plus vraie. Cette quête vire parfois à une conviction si absolue qu'elle ne tolère aucune remise en question, transforme une croyance en outil de pouvoir sur les autres. Une vérité vraiment solide reste ouverte à être questionnée encore.",
    10: "Pluton en maison X marque la carrière d'une puissance transformatrice : une ambition qui vise le pouvoir réel plutôt que la simple reconnaissance, une réussite souvent construite à travers des crises professionnelles qui obligent à tout reconstruire. Cette intensité crée parfois des conflits marqués avec l'autorité ou la hiérarchie, pousse à un contrôle excessif de sa propre image publique par peur de perdre la maîtrise. Une réussite durable se construit aussi en partageant le pouvoir, pas seulement en le concentrant.",
    11: "Pluton en maison XI transforme les amitiés et les causes collectives en profondeur : des liens amicaux peu nombreux mais d'une intensité rare, un vrai pouvoir de mobilisation autour d'une cause vécue comme vitale. Cette intensité nourrit parfois une suspicion sur les motivations réelles des autres membres d'un collectif, ou transforme une cause commune en enjeu de pouvoir personnel. Une cause collective reste plus forte quand le pouvoir y est partagé plutôt que concentré.",
    12: "Pluton en maison XII loge la transformation dans l'invisible : des processus intérieurs profonds, souvent vécus en silence, une confrontation avec des peurs archaïques ou un inconscient particulièrement actif, parfois à travers les rêves. Cette intensité intérieure reste parfois totalement cachée, se transforme en angoisse diffuse ou en sabotage silencieux plutôt que d'être affrontée consciemment. Une transformation vécue seul gagne à être, au moins en partie, reconnue et nommée.",
  },
  juno: {
    1: "Junon en maison I mêle le besoin de partenaire à l'identité elle-même : on se sent plus pleinement soi une fois engagé·e, et le choix d'un compagnon ou d'une compagne pèse directement sur l'image qu'on projette au monde. Le risque est de laisser le statut de couple définir qui on est, jusqu'à se sentir incomplet·e ou invisible en dehors d'une relation. Une identité qui tient debout seule reste pourtant ce qui rend, ensuite, le lien à deux plus solide.",
    2: "Junon en maison II lie l'engagement aux ressources partagées : bâtir une sécurité matérielle commune, un compte joint, un projet financier à deux, devient une vraie preuve d'amour, presque plus parlante que les mots. L'argent peut alors devenir un terrain de jalousie ou de rapport de force dans le couple, une dépense jugée excessive prenant vite des allures de trahison. La valeur d'un partenaire, cependant, ne se mesure pas à ce qu'il apporte matériellement.",
    3: "Junon en maison III fait de la conversation le cœur du lien : on s'engage envers quelqu'un avec qui parler ne s'épuise jamais, et le quotidien à deux ressemble à un échange continu, messages, discussions, petites nouvelles partagées. Le risque est de tout commenter sans jamais vraiment approfondir, un couple qui bavarde beaucoup mais évite les sujets qui demanderaient un vrai courage. Certaines choses gagnent à être dites lentement plutôt qu'évoquées entre deux banalités.",
    4: "Junon en maison IV rêve d'un foyer avant tout : le partenaire devient une famille à part entière, et l'engagement se mesure à la capacité de construire un nid, un lieu où chacun se sent vraiment chez soi. On reproduit parfois, sans le vouloir, des schémas hérités de la famille d'origine dans la façon d'aimer ou d'attendre d'être aimé·e, jusqu'à confondre un vieux besoin d'enfance avec un vrai choix d'adulte. Un foyer réellement solide se construit pourtant à deux, pas seulement en réparant ce qui manquait avant.",
    5: "Junon en maison V veut que l'amour reste vivant, joueur, un peu spectaculaire : la romance, les surprises, les gestes créatifs comptent presque autant que l'engagement lui-même. Ce placement redoute l'ennui du quotidien plus que tout, avec parfois un besoin de drame ou de rebondissement pour continuer à sentir que la flamme est là. Un amour qui dure n'a pourtant pas besoin d'être constamment mis en scène pour rester réel.",
    6: "Junon en maison VI construit l'engagement dans le quotidien concret : partager les tâches, s'organiser ensemble, se rendre utile l'un à l'autre, voilà ce qui, ici, vaut toutes les déclarations. Le partenaire devient un vrai coéquipier de vie, et l'harmonie du couple se juge souvent à la fluidité des petites choses. Le revers est de laisser la relation glisser dans la routine pure, une liste de tâches partagées plutôt qu'un lien vivant, jusqu'à oublier qu'un couple reste aussi fait pour se réjouir, pas seulement pour fonctionner.",
    7: "Junon en maison VII est chez elle : le partenariat occupe une place centrale dans l'existence, et une grande partie de l'identité se construit à travers le regard et la présence de l'autre. L'engagement n'est ici jamais anodin, ce placement sait instinctivement ce qu'exige une relation à long terme. Le piège consiste à faire dépendre toute sa valeur du fait d'être en couple, comme si être seul·e signifiait forcément être incomplet·e.",
    8: "Junon en maison VIII cherche une intimité totale, sans zone d'ombre entre deux personnes : le vrai engagement passe ici par la fusion, le partage des secrets les plus enfouis, une confiance mise à l'épreuve avant d'être pleinement accordée. Les ressources communes, l'argent, l'héritage, les dettes, deviennent des enjeux profonds, presque aussi intenses que les sentiments eux-mêmes. Une intimité aussi intense n'a pourtant pas besoin d'être testée sans arrêt pour rester vraie.",
    9: "Junon en maison IX s'attache à quelqu'un qui élargit l'horizon : un partenaire venu d'ailleurs, une histoire d'amour qui commence en voyage, ou simplement une vision du monde à partager et à faire grandir ensemble. L'engagement se nourrit d'apprentissage mutuel, et une relation qui n'apporte plus rien de nouveau à découvrir finit par sembler étroite. Le risque est d'idéaliser un partenaire pour ce qu'il représente culturellement ou intellectuellement, plutôt que de le voir tel qu'il est réellement, avec ses limites.",
    10: "Junon en maison X mêle l'engagement à l'image sociale et à la réussite : le choix d'un partenaire pèse sur la réputation, la carrière, parfois même sur l'ambition professionnelle des deux personnes. Un couple qui s'affiche, qui progresse ensemble aux yeux de tous, compte réellement ici. Le revers est de choisir, sans se l'avouer, un partenaire pour ce qu'il représente socialement plutôt que pour ce qu'il est en privé.",
    11: "Junon en maison XI veut un partenaire qui soit d'abord un ami, un allié dans les mêmes causes, les mêmes rêves d'avenir : l'amitié précède souvent l'amour, et le couple ressemble à une équipe engagée pour quelque chose de plus grand qu'elle-même. Ce placement s'épanouit dans des relations moins conventionnelles, où le groupe d'amis compte presque autant que le partenaire. Le risque est de garder une distance émotionnelle sous couvert de camaraderie, comme si nommer l'intimité menaçait la liberté du lien.",
    12: "Junon en maison XII vit l'engagement de façon discrète, parfois secrète : une histoire qu'on ne montre pas tout de suite, un attachement qui se construit en coulisses avant d'être révélé au grand jour. Ce placement peut ressentir un lien comme « écrit d'avance », presque karmique, avec une envie de tout donner à l'autre au point de s'oublier soi-même. Un amour vécu en retrait n'a pourtant pas besoin de rester invisible pour être réel.",
  },
  chiron: {
    1: "Chiron en maison I loge la blessure au cœur même de l'identité : un sentiment persistant de ne pas être tout à fait à l'aise dans sa propre peau, presque aussi loin que remontent les souvenirs. On adapte souvent sa personnalité pour être accepté·e, quitte à perdre de vue qui l'on est vraiment en dessous du masque. Ce placement finit pourtant souvent par incarner, aux yeux des autres, une authenticité rare, précisément parce qu'il a dû apprendre à se l'autoriser à lui-même.",
    2: "Chiron en maison II touche la valeur qu'on s'accorde et la sécurité matérielle, avec une inquiétude de fond sur ce qu'on possède ou ce qu'on mérite, même quand la situation réelle est stable. Cela peut se traduire par une peur chronique de manquer, ou à l'inverse par un désintérêt marqué pour l'argent qui masque en fait une vieille honte. Ce placement apprend souvent, avec le temps, à aider les autres à retrouver leur propre valeur, au-delà de ce qu'ils possèdent.",
    3: "Chiron en maison III garde la trace d'un apprentissage difficile ou d'une parole jamais vraiment entendue, une impression d'avoir été jugé·e lent·e ou incompris·e dès l'enfance, parfois une vraie difficulté scolaire. Le quotidien peut alors se marquer par un besoin de tout réexpliquer, ou par un silence prudent dès qu'un sujet compte vraiment. Ce placement développe souvent, à l'inverse, un vrai don pour rendre une idée compliquée limpide pour quelqu'un d'autre.",
    4: "Chiron en maison IV porte une blessure liée au foyer d'origine, une vie de famille douloureuse, instable, ou simplement privée de la sécurité qu'un enfant est en droit d'attendre. Ce placement peut reproduire, sans le vouloir, des schémas familiaux hérités, ou au contraire chercher à tout contrôler chez soi pour ne plus jamais revivre ce chaos. Il finit pourtant souvent par bâtir, pour lui-même et pour les autres, un foyer réellement sûr.",
    5: "Chiron en maison V touche l'expression créative et le besoin d'être aimé·e tel qu'on est, pas seulement pour ce qu'on produit : un talent d'enfant qui n'a peut-être jamais été pleinement vu ou encouragé. Cela peut mener soit à chercher l'approbation à travers la performance, soit à cacher complètement un don de peur du jugement. Ce placement retrouve souvent, avec le temps, une joie créative sincère, et aide fréquemment d'autres personnes, parfois des enfants, à faire de même.",
    6: "Chiron en maison VI se loge dans le corps, la santé ou le travail quotidien : un mal chronique difficile à nommer, ou le sentiment d'être un simple rouage au travail plutôt qu'une personne. Le risque est de prendre soin de tout le monde sauf de soi-même, jusqu'à l'épuisement. Ce placement devient très souvent, littéralement, un métier d'aide ou de soin, avec une vraie leçon à transmettre sur un rythme de vie durable.",
    7: "Chiron en maison VII touche le partenariat, souvent avec le souvenir d'une relation marquante, parfois observée chez les parents, qui a laissé une blessure sur ce qu'un couple équilibré devrait être. Ce placement peut reproduire des dynamiques déséquilibrées, ou fuir l'engagement par peur de les revivre. Il devient pourtant fréquemment un guide précieux pour d'autres personnes qui traversent, elles aussi, des difficultés relationnelles.",
    8: "Chiron en maison VIII touche une expérience précoce de perte, de crise, ou de trahison, un moment où la confiance ou le pouvoir ont basculé de façon marquante. Ce placement peut développer un malaise profond face à la vulnérabilité ou à la dépendance envers quelqu'un d'autre, avec un besoin de tout contrôler dans l'intimité ou les ressources partagées. Il devient souvent, en retour, exceptionnellement outillé pour accompagner d'autres personnes à travers leurs propres crises.",
    9: "Chiron en maison IX touche une croyance ou un système d'enseignement qui a déçu ou trompé, un professeur, une religion, une philosophie en qui la confiance s'est brisée. Ce placement peut basculer soit vers une certitude rigide qui refuse le doute, soit vers un refus de s'engager dans n'importe quelle croyance. Il aide pourtant souvent les autres à construire un sens qui leur appartienne vraiment, loin de tout dogme reçu tout fait.",
    10: "Chiron en maison X touche la réussite sociale et la reconnaissance, avec le sentiment d'avoir échoué aux yeux du monde, ou d'une figure d'autorité importante, à un moment décisif. Ce placement peut pousser à travailler sans relâche pour prouver sa valeur, ou au contraire à éviter l'ambition par peur de l'échec. Il devient souvent, avec le temps, une figure publique respectée, en particulier dans des métiers tournés vers l'aide aux autres.",
    11: "Chiron en maison XI touche l'appartenance à un groupe, avec le souvenir d'avoir été exclu·e ou mis·e à l'écart par des pairs, parfois dès l'école. Ce placement se méfie facilement des groupes, restant en marge même quand une place lui est offerte. Il devient pourtant souvent celui ou celle qui construit, pour les autres, une communauté réellement accueillante, où personne n'est laissé de côté.",
    12: "Chiron en maison XII touche quelque chose de difficile à nommer, une tristesse ancienne ou une perte dont l'origine reste floue, parfois antérieure aux souvenirs conscients. Ce placement peut éviter d'y faire face, en s'anesthésiant ou en se sacrifiant en silence pour les autres. Il développe pourtant souvent, avec le temps, une capacité de guérison discrète, un soin apporté aux autres d'une façon qui ne se voit pas toujours mais qui compte profondément.",
  },
  vertex: {
    1: "Le Vertex en maison I fait de la rencontre elle-même un moment fondateur pour l'identité : se lier à quelqu'un change littéralement la façon dont on se voit soi-même. Ce placement rend le premier contact particulièrement marquant, presque comme un avant/après. Une rencontre vraiment fondatrice ici transforme durablement l'image qu'on a de soi, pas seulement l'humeur du moment.",
    2: "Le Vertex en maison II lie les rencontres marquantes à la sécurité matérielle et à la valeur personnelle : une relation qui compte redéfinit souvent, en même temps, le rapport à l'argent ou à ce qu'on estime mériter. Ce placement peut faire naître un lien important autour d'un projet financier commun ou d'une aide concrète reçue. La vraie valeur d'une telle rencontre, cependant, ne se mesure jamais à ce qu'elle apporte matériellement.",
    3: "Le Vertex en maison III lie les rencontres marquantes à la parole et au voisinage proche : un échange, une personne croisée dans l'entourage immédiat, une conversation qui prend soudain une tout autre ampleur. Ce placement peut transformer une simple connaissance en lien décisif, presque sans prévenir. Certaines rencontres qui semblaient anodines au départ se révèlent, avec le recul, parmi les plus marquantes.",
    4: "Le Vertex en maison IV lie les rencontres marquantes au foyer et à la famille : une personne qui devient famille, un lien qui redéfinit ce que \"chez-soi\" veut dire. Ce placement fait souvent de la rencontre la plus marquante celle qui, au fond, ramène vers un sentiment d'appartenance. Un tel lien construit, une fois noué, un ancrage rarement remis en question.",
    5: "Le Vertex en maison V lie les rencontres marquantes à la romance et à la créativité : c'est ici que se joue le scénario classique de la rencontre amoureuse qui change tout. Ce placement associe souvent le lien le plus marquant à un contexte de jeu, de plaisir ou de création partagée. Un amour qui naît ici garde, longtemps après, le souvenir de sa légèreté initiale.",
    6: "Le Vertex en maison VI lie les rencontres marquantes au travail quotidien ou à la santé : un ou une collègue, une personne croisée dans un contexte de soin, un lien qui s'installe dans la routine avant de devenir essentiel. Ce placement fait souvent naître un attachement fort là où on ne l'attendait pas, entre deux tâches ordinaires. La valeur de ce genre de lien tient justement à ce qu'il a traversé le quotidien sans jamais se dissoudre dedans.",
    7: "Le Vertex en maison VII est chez lui : le partenariat occupe naturellement une place centrale, et une rencontre marquante y prend souvent des allures de destin. Ce placement correspond au scénario le plus classique du \"lien écrit d'avance\", celui qu'on associe spontanément au Vertex. Le risque est de céder trop vite à cette impression de fatalité, sans prendre le temps de vérifier ce que le lien vaut réellement au quotidien.",
    8: "Le Vertex en maison VIII lie les rencontres marquantes à la crise et à l'intimité profonde : un lien qui naît dans un moment de vulnérabilité, de deuil ou de grande transformation partagée. Ce placement rend certaines rencontres presque irréversibles une fois vécues, tant l'intensité initiale marque durablement. Ce genre de lien change rarement une personne à moitié : il transforme, ou il s'arrête net.",
    9: "Le Vertex en maison IX lie les rencontres marquantes au voyage et à l'ailleurs : une personne rencontrée en dehors de son cadre habituel, une vision du monde qui bascule après cette rencontre. Ce placement associe souvent le lien le plus décisif à un enseignant, un mentor, ou quelqu'un venu d'une culture différente. Une rencontre marquante ici élargit durablement une façon de voir, bien au-delà de la relation elle-même.",
    10: "Le Vertex en maison X lie les rencontres marquantes à la carrière et à la réussite visible : une personne croisée dans un contexte professionnel qui change une trajectoire entière. Ce placement fait parfois de la rencontre la plus marquante celle qui ouvre une porte publique inattendue. Un tel lien, une fois formé, se voit souvent aussi de l'extérieur, pas seulement dans l'intimité du couple.",
    11: "Le Vertex en maison XI lie les rencontres marquantes à un groupe ou une cause partagée : un lien qui naît d'abord dans l'amitié, un projet collectif, ou un idéal commun avant de devenir central. Ce placement associe souvent la rencontre la plus décisive à une communauté plutôt qu'à un contexte purement romantique. Ce genre de lien se construit dans la durée, porté par ce qu'on bâtit ensemble plus que par l'attirance seule.",
    12: "Le Vertex en maison XII lie les rencontres marquantes au secret ou à l'invisible : un lien vécu en retrait, parfois difficile à nommer clairement, presque toujours chargé d'une intensité émotionnelle rare. Ce placement peut rendre une rencontre marquante particulièrement difficile à partager avec l'entourage, comme si elle appartenait à un espace à part. Ce genre de lien laisse pourtant souvent une empreinte profonde, même quand il reste discret ou de courte durée.",
  },
  partMarriage: {
    1: "La Part du Mariage en maison I mêle le mariage à l'identité elle-même : on se sent plus pleinement soi une fois engagé·e durablement, et le choix d'un partenaire pèse directement sur l'image qu'on projette. Le risque est de laisser le statut marital définir qui on est, au point de se sentir incomplet·e hors d'une union officielle. Une identité qui tient debout seule reste pourtant ce qui rend, ensuite, l'union plus solide.",
    2: "La Part du Mariage en maison II lie l'union durable aux ressources partagées : bâtir une sécurité matérielle commune devient une vraie preuve d'engagement, presque plus parlante que les mots. L'argent peut alors devenir un terrain de tension dans le couple, une dépense jugée excessive prenant vite des allures de trahison. La valeur d'une union, cependant, ne se mesure pas à ce qu'elle apporte matériellement.",
    3: "La Part du Mariage en maison III fait de la conversation le socle de l'union durable : on construit un engagement avec quelqu'un avec qui parler ne s'épuise jamais, et le quotidien à deux ressemble à un échange continu. Le risque est de tout commenter sans jamais vraiment approfondir. Certaines choses gagnent à être dites lentement plutôt qu'évoquées entre deux banalités.",
    4: "La Part du Mariage en maison IV rêve d'un foyer avant tout : l'union se mesure à la capacité de construire un vrai nid, un lieu où chacun se sent pleinement chez soi. On reproduit parfois, sans le vouloir, des schémas hérités de la famille d'origine dans la façon de s'engager. Un foyer réellement solide se construit pourtant à deux, pas seulement en réparant ce qui manquait avant.",
    5: "La Part du Mariage en maison V veut que l'union reste vivante et joueuse : la romance, les surprises, les gestes créatifs comptent presque autant que l'engagement lui-même. Ce placement redoute l'ennui du quotidien plus que tout. Une union qui dure n'a pourtant pas besoin d'être constamment mise en scène pour rester réelle.",
    6: "La Part du Mariage en maison VI construit l'union dans le quotidien concret : partager les tâches, s'organiser ensemble, se rendre utile l'un à l'autre, voilà ce qui, ici, vaut toutes les déclarations. Le revers est de laisser l'union glisser dans la routine pure, une liste de tâches partagées plutôt qu'un lien vivant. Une union reste pourtant aussi faite pour se réjouir, pas seulement pour fonctionner.",
    7: "La Part du Mariage en maison VII est chez elle : le partenariat occupe une place centrale dans l'existence, et l'engagement n'y est jamais anodin. Ce placement sait instinctivement ce qu'exige une union à long terme. Le piège consiste à faire dépendre toute sa valeur du fait d'être marié·e, comme si être seul·e signifiait forcément être incomplet·e.",
    8: "La Part du Mariage en maison VIII cherche une intimité totale, sans zone d'ombre entre deux personnes : l'union durable passe ici par la fusion, une confiance mise à l'épreuve avant d'être pleinement accordée. Les ressources communes, l'argent, l'héritage, les dettes, deviennent des enjeux profonds. Une intimité aussi intense n'a pourtant pas besoin d'être testée sans arrêt pour rester vraie.",
    9: "La Part du Mariage en maison IX s'attache à un engagement qui élargit l'horizon : un partenaire venu d'ailleurs, une union qui se nourrit d'apprentissage mutuel et d'une vision du monde à faire grandir ensemble. Le risque est d'idéaliser un partenaire pour ce qu'il représente culturellement plutôt que de le voir tel qu'il est. Une union qui n'apporte plus rien de nouveau à découvrir finit pourtant par sembler étroite.",
    10: "La Part du Mariage en maison X mêle l'union à l'image sociale et à la réussite : le choix d'un partenaire pèse sur la réputation, parfois sur l'ambition professionnelle des deux personnes. Un couple marié qui progresse ensemble aux yeux de tous compte réellement ici. Le revers est de choisir, sans se l'avouer, un partenaire pour ce qu'il représente socialement plutôt que pour ce qu'il est en privé.",
    11: "La Part du Mariage en maison XI veut un partenaire qui soit d'abord un allié, engagé dans les mêmes causes, les mêmes rêves d'avenir : l'amitié précède souvent l'union, qui ressemble à une équipe engagée pour quelque chose de plus grand qu'elle-même. Ce placement s'épanouit dans des unions moins conventionnelles. Le risque est de garder une distance émotionnelle sous couvert de camaraderie.",
    12: "La Part du Mariage en maison XII vit l'engagement de façon discrète, parfois secrète : une union qu'on ne montre pas tout de suite, un attachement qui se construit en coulisses avant d'être révélé au grand jour. Ce placement peut ressentir l'union comme « écrite d'avance », presque karmique. Un amour vécu en retrait n'a pourtant pas besoin de rester invisible pour être réel.",
  },
  // L'Ascendant définit toujours le tout début de la maison I (dans les 4
  // systèmes de maisons proposés ici), donc une seule entrée suffit : il ne
  // tombera jamais dans une autre maison. Le complément dynamique (quelles
  // planètes partagent cette maison I) est ajouté séparément par
  // ascendantHouseOneOccupantsText dans compose.ts, à partir du thème
  // complet plutôt que de ce texte statique seul.
  asc: {
    1: "La maison I est celle de la toute première impression : ce que les autres perçoivent de vous avant même d'avoir échangé un mot, votre allure, votre posture, la façon dont vous entrez dans une pièce. C'est la maison la plus visible du thème, souvent ce par quoi on vous reconnaît en premier, avant même que votre Soleil ou votre Lune n'aient eu le temps de se révéler.",
  },
};
